# SPDX-License-Identifier: MIT
# Compare the candidate's ps tables with procps ps run immediately after in the
# same pid namespace, and both with the live /proc process set (takeover root).
import os
own = os.getpid()
live = {int(n) for n in os.listdir('/proc') if n.isdigit()} - {own}


def table(path, col):
    # A row starts at a line whose PID column is numeric; any other line
    # continues the previous row (a command line with embedded newlines).
    lines = open(path).read().splitlines()
    rows, last = {}, None
    for line in lines[1:]:
        f = line.split()
        if len(f) > col and f[col].isdigit():
            last = int(f[col])
            rows[last] = line
        elif last is not None:
            rows[last] += '\n' + line
    return (lines[0] if lines else ''), rows


def role(pid):
    data = open('/proc/%d/stat' % pid).read()
    return '%s/%s' % (data[data.index('(') + 1:data.rindex(')')], data[data.rindex(')') + 2:].split()[0])


tables = {}
for key, col in (('e', 0), ('A', 0), ('aux', 1), ('ef', 1)):
    tables[key] = (table('c-%s.out' % key, col), table('g-%s.out' % key, col))
print('enumeration ' + ' '.join('%s=%s' % (k, 'match' if set(c[1]) == live else 'differ %r' % sorted(set(c[1]) ^ live))
                                for k, (c, g) in tables.items()) + ' processes=%d' % len(live))
print('header ' + ' '.join('%s=%s' % (k, 'match' if c[0] == g[0] else 'differ %r %r' % (c[0], g[0]))
                           for k, (c, g) in tables.items()))
for pid in sorted(live - {1}, key=lambda p: (role(p), p)):
    parts = []
    for k, (c, g) in tables.items():
        cr, gr = c[1].get(pid), g[1].get(pid)
        if cr == gr:
            parts.append('%s=match' % k)
        else:
            heads = g[0].split()
            cf, gf = (cr or '').split(), (gr or '').split()
            bad = [heads[i] if i < len(heads) else str(i) for i in range(max(len(cf), len(gf)))
                   if (cf[i] if i < len(cf) else None) != (gf[i] if i < len(gf) else None)]
            parts.append('%s=differ(%s) candidate=%r procps=%r' % (k, ','.join(bad), cr, gr))
    print('%s: %s' % (role(pid), ' '.join(parts)))
